<?php
declare(strict_types=1);
/**
 * Shared skip link and site header.
 *
 * @var string $skipTarget
 * @var string $skipLabel
 * @var ?string $activeNav 'writing' | 'about' | null
 * @var bool|null $showReadingProgress
 */
$showReadingProgress = $showReadingProgress ?? false;
?>
<body>
  <a class="skip-link" href="<?= htmlspecialchars($skipTarget, ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($skipLabel, ENT_QUOTES, 'UTF-8') ?></a>
  <header class="site-header"><div class="shell nav-row"><div class="brand-nav"><a class="wordmark" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/" aria-label="<?= __('{site} home', ['site' => $siteName]) ?>"><?= htmlspecialchars($siteName, ENT_QUOTES, 'UTF-8') ?></a><nav aria-label="<?= __('Primary') ?>"><a<?= $activeNav === 'writing' ? ' aria-current="page"' : '' ?> href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/"><?= __('Writing') ?></a><?php foreach ($navPages ?? [] as $navPage): ?><a<?= $activeNav === $navPage['slug'] ? ' aria-current="page"' : '' ?> href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/<?= htmlspecialchars($navPage['slug'], ENT_QUOTES, 'UTF-8') ?>/"><?= htmlspecialchars($navPage['title'], ENT_QUOTES, 'UTF-8') ?></a><?php endforeach; ?><a class="rss-link" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/rss.xml">RSS</a></nav></div><div class="header-tools"><?php if ($showReadingProgress): ?><div class="header-reading-progress" role="progressbar" aria-label="<?= __('Reading progress') ?>" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span class="progress-track" aria-hidden="true"><span class="progress-fill"></span></span><span class="progress-value">0%</span></div><?php endif; ?><div class="header-search-wrap"><button type="button" class="header-search-trigger" id="search-trigger" aria-label="<?= __('Search writing (⌘K)') ?>" title="<?= __('Search writing (⌘K)') ?>" aria-expanded="false" aria-controls="search-dropdown"><span class="icon" aria-hidden="true">search</span><span class="search-trigger-shortcut">⌘K</span></button><div class="header-search-dropdown" id="search-dropdown" hidden><div class="search-field"><span class="icon" aria-hidden="true">search</span><input type="search" id="site-search" placeholder="<?= __('Search writing…') ?>" aria-label="<?= __('Search articles') ?>" data-read-label="<?= __('Read {title}') ?>" data-empty-label="<?= __('No matching articles.') ?>" autocomplete="off"><button type="button" class="search-close-btn" id="search-close" aria-label="<?= __('Close search') ?>"><span class="icon" aria-hidden="true">close</span></button></div><div id="search-results" class="header-search-results article-list" hidden></div></div></div><div class="theme-switcher" role="group" aria-label="<?= __('Display mode') ?>"><button type="button" data-theme-set="auto" title="<?= __('System') ?>" aria-pressed="true"><span class="icon" aria-hidden="true">brightness_auto</span><span class="sr-only"><?= __('System') ?></span></button><button type="button" data-theme-set="light" title="<?= __('Light') ?>" aria-pressed="false"><span class="icon" aria-hidden="true">light_mode</span><span class="sr-only"><?= __('Light') ?></span></button><button type="button" data-theme-set="dark" title="<?= __('Dark') ?>" aria-pressed="false"><span class="icon" aria-hidden="true">dark_mode</span><span class="sr-only"><?= __('Dark') ?></span></button></div><button type="button" class="theme-cycle" data-theme-cycle aria-label="<?= __('Display mode: {current}. Activate to use {next} mode.', ['current' => \HolyMD\I18n\Translator::text('System'), 'next' => \HolyMD\I18n\Translator::text('Light')]) ?>" title="<?= __('Change display mode') ?>"><span class="icon" aria-hidden="true">brightness_auto</span></button></div></div></header>
